# Code generated by Claude
"""
Measurement only (David, 2026-10-28): peak actual joint jerk (150 Hz, rad/s^3) at every phase boundary and mid-phase of the manipulation phases, side by side for several runs.

    python experiments/comp_jerk_table.py DIR [DIR ...]      (DIR = data/arm_motion/comp/<name> after experiments/left_arm_motion_report.py; numpy only)

Boundary into a phase = the "peak jerk 150 Hz" of the +-0.5 s window of the boundary whose "to" is that phase (the carry boundary, into PLACE: OVER, is the window of the "PLACE: starting"
row's UP end: its value is the one of experiments/carry_boundary_analysis.py "boundary window"). Mid-phase = the peak over the middle half of the phase. Markdown table on stdout.
"""
import json
import re
import sys
from pathlib import Path

PHASES = ["PICK: OVER", "PICK: DOWN", "PICK: IN", "PICK: CLOSE", "PICK: UP", "PLACE: OVER", "PLACE: DOWN", "PLACE: OPEN", "PLACE: BACK", "PLACE: HOME"]
runs = {}
for d in sys.argv[1:]:
    m = json.loads((Path(d) / "metrics.json").read_text())
    row = {}
    for ph in PHASES:
        mid = next((p["peak_jerk_tick_mid"] for p in m["phases"] if p["key"].endswith(ph)), None)
        bnd = [b for b in m["boundaries"] if b["to"].endswith(ph)]
        if ph == "PLACE: OVER":                                           # the boundary into PLACE: OVER is the window of the "PLACE: starting -> PLACE: OVER" row
            bnd = [b for b in m["boundaries"] if b["to"].endswith("PLACE: OVER")]
        row[ph] = (None if not bnd else bnd[0]["peak_jerk_tick_window"], mid)
    runs[Path(d).name] = row
names = list(runs)
print("| phase | " + " | ".join(f"{n} boundary into / mid" for n in names) + " |")
print("|---|" + "---|" * len(names))
for ph in PHASES:
    cells = []
    for n in names:
        b, mid = runs[n][ph]
        f = lambda x: "n/a" if x is None or x != x else f"{x:.0f}" if x >= 100 else f"{x:.1f}"
        cells.append(f"{f(b)} / {f(mid)}")
    print(f"| {ph} | " + " | ".join(cells) + " |")
